package rentivo_backend.service;
import jakarta.persistence.EntityNotFoundException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import rentivo_backend.dto.ListingDtos.*; import rentivo_backend.entity.*; import rentivo_backend.repository.*; import java.time.LocalDateTime; import java.util.*;
@Service public class ListingService { private final ListingRepository listings; private final UserRepository users; private final CategoryRepository cats; private final CategoryFieldRepository fields;
 public ListingService(ListingRepository l,UserRepository u,CategoryRepository c,CategoryFieldRepository f){listings=l;users=u;cats=c;fields=f;}
 @Transactional public Listing create(CreateListingRequest r,Long userId){User owner=users.findById(userId).orElseThrow(()->new EntityNotFoundException("User not found"));if(!owner.isActive()||!owner.isPhoneVerified())throw new SecurityException("Verified active user required");Category cat=cats.findById(r.categoryId()).orElseThrow(()->new EntityNotFoundException("Category not found"));if(!cat.isActive())throw new IllegalStateException("Category is inactive");if(!owner.getPhone().equals(r.contactPhone()))throw new IllegalArgumentException("Contact number must match the verified login mobile number");Listing l=new Listing();l.setTitle(r.title());l.setCategory(cat);l.setListingType(r.listingType());l.setPrice(r.price());l.setPriceUnit(r.priceUnit());l.setDescription(r.description());l.setState(r.state());l.setCity(r.city());l.setLocality(r.locality());l.setPincode(r.pincode());l.setAddress(r.address());l.setLatitude(r.latitude());l.setLongitude(r.longitude());l.setContactPhone(r.contactPhone());l.setOwner(owner);l.setStatus(Listing.Status.PENDING);l.setCreatedAt(LocalDateTime.now()); validateFields(cat,r.fields()); if(r.fields()!=null)for(var e:r.fields().entrySet()){CategoryField f=fields.findById(e.getKey()).orElseThrow(()->new IllegalArgumentException("Invalid category field: "+e.getKey()));ListingFieldValue v=new ListingFieldValue();v.setListing(l);v.setField(f);v.setValue(e.getValue());l.getFieldValues().add(v);} return listings.save(l);}
 public List<Listing> mine(Long uid){return listings.findByOwnerIdAndStatusNot(uid,Listing.Status.DELETED);} @Transactional public Listing update(Long uid,Long id,CreateListingRequest r){Listing l=listings.findById(id).orElseThrow(()->new EntityNotFoundException("Listing not found"));if(!l.getOwner().getId().equals(uid))throw new SecurityException("You can edit only your own listing");if(!l.getOwner().getPhone().equals(r.contactPhone()))throw new IllegalArgumentException("Contact number must match verified mobile");Category cat=cats.findById(r.categoryId()).orElseThrow(()->new EntityNotFoundException("Category not found"));if(!cat.isActive())throw new IllegalStateException("Category is inactive");validateFields(cat,r.fields());l.setTitle(r.title());l.setCategory(cat);l.setListingType(r.listingType());l.setPrice(r.price());l.setPriceUnit(r.priceUnit());l.setDescription(r.description());l.setState(r.state());l.setCity(r.city());l.setLocality(r.locality());l.setPincode(r.pincode());l.setAddress(r.address());l.setLatitude(r.latitude());l.setLongitude(r.longitude());l.setContactPhone(r.contactPhone());l.setStatus(Listing.Status.PENDING);l.setUpdatedAt(LocalDateTime.now());l.getFieldValues().clear();if(r.fields()!=null)for(var e:r.fields().entrySet()){CategoryField f=fields.findById(e.getKey()).orElseThrow(()->new IllegalArgumentException("Invalid category field: "+e.getKey()));ListingFieldValue v=new ListingFieldValue();v.setListing(l);v.setField(f);v.setValue(e.getValue());l.getFieldValues().add(v);}return listings.save(l);} private void validateFields(Category cat,Map<Long,String> values){for(CategoryField f:cat.getFields())if(f.isRequired()&&(values==null||values.get(f.getId())==null||values.get(f.getId()).isBlank()))throw new IllegalArgumentException("Required field missing: "+f.getName());if(values!=null)for(Long id:values.keySet()){CategoryField f=fields.findById(id).orElseThrow(()->new IllegalArgumentException("Invalid category field: "+id));if(!f.getCategory().getId().equals(cat.getId()))throw new IllegalArgumentException("Field does not belong to category");}}
@Transactional public void delete(Long uid,Long id){Listing l=listings.findById(id).orElseThrow(()->new EntityNotFoundException("Listing not found"));if(!l.getOwner().getId().equals(uid))throw new SecurityException("You can delete only your own listing");l.setStatus(Listing.Status.DELETED);listings.save(l);} }
